// The code and parameter tables of the VC-1 parser: SMPTE 421M's variable-length codes, the AC escape tables, the picture parameter
// tables, and the scans, as the all-WGSL decoder this parser replaced carried them, read back from its verified code lookups.

/// One variable-length code table: each symbol's code, right-aligned, and its length in bits, in symbol order.
/// `symbols` holds the symbols when they are not 0 to n - 1, as for the AC coefficient tables.
pub struct CodeTable {
    pub codes: &'static [u32],
    pub lengths: &'static [u8],
    pub symbols: &'static [u16],
}

/// IMODE, the bitplane coding mode.
pub const BITPLANE_MODE: CodeTable = CodeTable { codes: &[0, 2, 1, 3, 1, 2, 3], lengths: &[4, 2, 3, 2, 4, 3, 3], symbols: &[] };
